package com.codegym.controller;
import com.codegym.dao.ProductDAO; import com.codegym.model.Product; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; import java.sql.SQLException;
@WebServlet("/products") public class ProductServlet extends HttpServlet {
  private final ProductDAO dao=new ProductDAO();
  protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{String a=req.getParameter("action");if(a==null)a="list";switch(a){case "create"->req.getRequestDispatcher("/product/form.jsp").forward(req,resp);case "edit","view"->show(req,resp,a.equals("edit")?"/product/form.jsp":"/product/view.jsp");case "delete"->{dao.delete(Integer.parseInt(req.getParameter("id")));resp.sendRedirect("products");}default->{req.setAttribute("products",dao.findAll());req.getRequestDispatcher("/product/list.jsp").forward(req,resp);}}}catch(SQLException e){throw new ServletException(e);}}
  private void show(HttpServletRequest req,HttpServletResponse resp,String view)throws SQLException,ServletException,IOException{Product p=dao.findById(Integer.parseInt(req.getParameter("id")));if(p==null){resp.sendError(404);return;}req.setAttribute("product",p);req.getRequestDispatcher(view).forward(req,resp);}
  protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{req.setCharacterEncoding("UTF-8");String id=req.getParameter("id");dao.save(new Product(id==null||id.isBlank()?0:Integer.parseInt(id),req.getParameter("name"),Double.parseDouble(req.getParameter("price")),Integer.parseInt(req.getParameter("quantity"))));resp.sendRedirect("products");}catch(SQLException e){throw new ServletException(e);}}
}
